import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

gemm_scale_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void gemm_scale_kernel(
    const float* __restrict__ x, 
    const float* __restrict__ w,
    const float* __restrict__ b,
    const float* __restrict__ scale,
    float* __restrict__ out,
    int M, int K, int N
) {
    int row = blockIdx.x;
    int col = threadIdx.x;
    if (row < M && col < N) {
        float val = 0.0f;
        for(int k = 0; k < K; k++) {
            val += x[row * K + k] * w[col * K + k];
        }
        val += b[col];
        val *= scale[col];
        out[row * N + col] = val;
    }
}

torch::Tensor gemm_scale_cuda(
    torch::Tensor x, 
    torch::Tensor w,
    torch::Tensor b,
    torch::Tensor scale
) {
    auto M = x.size(0);
    auto K = x.size(1);
    auto N = w.size(0);
    auto out = torch::zeros({M, N}, x.options());
    dim3 grid(M);
    dim3 block(N);

    gemm_scale_kernel<<<grid, block>>>(
        x.data_ptr<float>(),
        w.data_ptr<float>(),
        b.data_ptr<float>(),
        scale.data_ptr<float>(),
        out.data_ptr<float>(),
        M, K, N
    );

    return out;
}
"""

gemm_scale_cpp_source = r"""
torch::Tensor gemm_scale_cuda(
    torch::Tensor x, 
    torch::Tensor w, 
    torch::Tensor b, 
    torch::Tensor scale
);
"""

gemm_scale = load_inline(
    name="gemm_scale",
    cpp_sources=gemm_scale_cpp_source,
    cuda_sources=gemm_scale_source,
    functions=["gemm_scale_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    """
    Optimized model that performs GEMM (general matrix multiplication),
    applies scaling, then batch normalization via a custom CUDA kernel.
    """
    def __init__(self, in_features, out_features, scale_shape, eps=1e-5, momentum=0.1):
        super(ModelNew, self).__init__()
        self.gemm = nn.Linear(in_features, out_features)
        self.scale = nn.Parameter(torch.randn(scale_shape))
        self.bn = nn.BatchNorm1d(out_features, eps=eps, momentum=momentum)
        self.gemm_scale = gemm_scale

    def forward(self, x):
        x = self.gemm_scale.gemm_scale_cuda(x, self.gemm.weight, self.gemm.bias, self.scale)
        x = self.bn(x)
        return x

batch_size = 128
in_features = 1024
out_features = 512
scale_shape = (out_features,)

def get_inputs():
    return [torch.randn(batch_size, in_features).cuda()]

def get_init_inputs():
    return [in_features, out_features, scale_shape]
